from engine import *

PART3 = "Part 3. Daily operations"
ALL = ["Operator", "Engineer", "Reliability", "HSE", "Manager"]

def blocks():
    b = []
    # ------------------------------------------------------------------ 11 Dashboard
    b += [H1(11, "Dashboard", ALL, PART3,
             "The Dashboard is the first page after sign-in. It shows the whole LLDPE unit as a 3D plant, lists the items that need attention today and summarises the knowledge base."),
          H2("Overview tab"),
          FIG("p3_dash", "The Dashboard, Overview tab.",
              [(1, "**Needs attention** chips. Green means no action. Amber means follow up.", "^latched trips$"),
               (2, "**Overview** and **Analytics** tabs.", "^Overview$"),
               (3, "View options for the 3D plant: Slow turn, Labels, Flow, Moving parts and Open set automatically.", "Slow turn", -4, -22),
               (4, "One button for each equipment set. Select a button to fly to that unit.", "^GA-1201A$"),
               (5, "**Whole plant** returns to the full view.", "^Whole plant$")], maxh=150),
          P("The **Needs attention** line counts five conditions: latched interlock trips, units that are not ready to start, units with overdue preventive work, high-severity document conflicts and units in breakdown at the last record. Select a chip to open the page that explains it."),
          H2("Using the 3D plant"),
          STEPS(["Drag with the mouse to rotate the view. Scroll to zoom. Hold the right mouse button, or use two fingers, to pan.",
                 "Select a unit tag above the model, or a label on the model, to fly to that unit.",
                 "Read the unit card that appears. It shows availability, breakdowns, downtime and forecast risk for the unit.",
                 "Select **Open equipment set** on the card to go to the equipment page, or select **Whole plant** to return."]),
          FIG("p3_dash_sel", "A unit selected on the Dashboard. The unit card opens beside the 3D view.", maxh=140),
          NOTE("tip", "Tick **Open set automatically** if you want a selected unit to open its equipment page at once."),
          P("Pipes are coloured by service so that you can follow a line across the plant. The legend under the model lists process liquid, nitrogen, steam and condensate, cooling water, lube and seal oil, and gas, vent and hydrogen. Green rings on the ground mark the hazard radius of each unit."),
          H2("Analytics tab"),
          P("The **Analytics** tab summarises the knowledge base and the maintenance history on one page. Every chart on this page is interactive: select a bar, a segment or a month to see the records behind it."),
          FIG("p3_dash_an", "The Dashboard, Analytics tab.",
              [(1, "Headline counts: equipment sets, documents, work orders, breakdowns, safety functions and lessons.", "^Equipment sets$"),
               (2, "**Knowledge base status**: indexed chunks, items added by users, items waiting for review and open answer feedback.", "^Knowledge base status$"),
               (3, "**Items requiring attention** and the high-severity data issues.", "^Items requiring attention$"),
               (4, "Charts for work orders by type, breakdown downtime by equipment and document approval status.", "^Work orders by type$"),
               (5, "Quick actions: **Ask the assistant**, **Add knowledge**, **Failure memory** and **Management summary**.", "^Ask the assistant$")], maxh=190),
          ]
    # ------------------------------------------------------------------ 12 My work
    b += [H1(12, "My work", ALL, PART3,
             "My work collects what concerns you personally: items waiting for your approval, items you have written, and your recent questions and activity."),
          FIG("p3_mywork", "The My work page, after a question has been asked.",
              [(1, "Items waiting for **your** approval. Empty for roles that cannot approve.", "^Waiting for my approval$"),
               (2, "Knowledge items you have written, with their status.", "^Items I wrote$"),
               (3, "Your recent questions to the AI Assistant.", "^My recent questions$"),
               (4, "Your recent activity, taken from the audit trail.", "^My recent activity$")], maxh=120),
          H2("How to use the page"),
          BUL(["Check **Waiting for my approval** at the start of each shift if you are an approver. Select an item to open it in Knowledge Studio.",
               "Use **Items I wrote** to follow a draft you submitted. The status moves from Draft to In review to Approved or Rejected.",
               "Open a question under **My recent questions** to read the answer again."]),
          NOTE("role", "Operators can write drafts and ask questions, but they cannot approve. Their **Waiting for my approval** list stays empty."),
          ]
    # ------------------------------------------------------------------ 13 Equipment Sets
    b += [H1(13, "Equipment Sets", ALL, PART3,
             "An equipment set gathers everything known about one machine. The page has a header with the main figures and twelve tabs that open the P&ID, the drawing, the datasheet, the interlock logic, the lessons and the maintenance history."),
          H2("The equipment list"),
          P("Select **Equipment Sets** in the sidebar to see the eight sets. Each card shows the tag, the name, the start-up status, the criticality and the main figures. Select a card to open the set."),
          H2("The equipment header"),
          FIG("p3_eq_tabs", "The header of an equipment page.",
              [(1, "Start-up status, flammability, set number, tag and criticality.", "^Start-up: ", 0, -4),
               (2, "**Ask the assistant** about this equipment. The question is limited to this set.", "^Ask the assistant about", -4, -12),
               (3, "The twelve tabs. The selected tab is underlined.", "^Overview$", -4, -14),
               (4, "Counts beside the tab names show how many records each tab holds.", "^Related assets", -4, -14)], maxh=60),
          P("Under the title, six tiles show availability, mean repair time, breakdowns, downtime, forecast risk and open data issues. **Inspect in 3D** opens the 3D model of the machine. **Export dossier** produces a printable summary of the equipment (see Chapter 37)."),
          H2("Overview tab"),
          P("The Overview tab answers the question: what do we know about this machine, and where is it?"),
          FIG("p3_eq_overview", "Overview tab of the Recycle Gas Compressor KC-4501.",
              [(1, "**What is on file**: tiles that open the P&ID, drawing, plot plan, datasheet, interlock logic, lessons, maintenance and key indicators.", "^What is on file for", 0, -14),
               (2, "**How it works**: a plain description of the machine and its process.", "^How it works$"),
               (3, "**At a glance**: size, weight, driver and interlock reference.", "^At a glance$"),
               (4, "**Place in the plant**: what feeds the unit and what it delivers to.", "^Place in the plant$"),
               (5, "**Location** in the unit, coloured by a measure you select.", "^Location of")]),
          H2("P&ID tab"),
          P("The P&ID tab shows the piping and instrumentation diagram of the unit. Chapter 15 describes how to read it and how to operate the valves."),
          FIG("p3_eq_pid", "P&ID tab.", maxh=130),
          H2("Drawing and 3D tab"),
          P("This tab shows the general arrangement drawing and the 3D model, with a bill of materials and the work orders for each component. Chapter 14 explains how to select parts."),
          FIG("p3_eq_ga", "Drawing and 3D tab.", maxh=130),
          H2("Indicators tab"),
          P("The Indicators tab gives the reliability and knowledge figures of the set: availability, mean repair time, mean time between failures, breakdowns, downtime, maintenance cost, the share of planned work, the forecast failure risk for the next 90 days, documents approved, lessons, open data issues and items added by users. A tag next to a figure shows whether it is on or off target. Select **Open the full performance page** to see the same figures for all sets."),
          FIG("p3_eq_perf", "Indicators tab.", maxh=70),
          H2("Plot plan tab"),
          P("The Plot plan tab shows where the unit stands in the plant and what is near it. Layers can be switched on for areas, heat map, hazard zones, muster points and gates, fire protection and walkways."),
          FIG("p3_eq_plot", "Plot plan tab.",
              [(1, "Switch between **Site overview** and the **Hazard simulator** (Chapter 31).", "^Site overview$"),
               (2, "Map layers: Areas, Heat map, Hazard zones, Muster and gates, Fire protection and Walkways.", "^Areas$", -4, -14),
               (3, "Facts about the selected unit: area, grid, elevation, fluid, hazard zones and nearest muster point.", "^Plant grid$"),
               (4, "**Dispatch operator** shows the route and walking time from the control room.", "^Dispatch operator$")], maxh=140),
          H2("Start-up readiness tab"),
          P("This tab decides whether the unit is ready to start. Chapter 17 describes it in full."),
          H2("Documents tab"),
          P("The Documents tab lists every document of the set. The top table shows the **document set coverage**: whether a P&ID, an equipment drawing, a datasheet, a plot plan and an interlock logic document exist for the set, and their approval status. The lower table lists all documents with their type, revision, approval status and effective date."),
          FIG("p3_eq_docs", "Documents tab.", maxh=120),
          H2("Datasheet tab"),
          P("The Datasheet tab shows the equipment datasheet as a searchable list of specifications, grouped by topic such as identification, driver, design and mechanical data. Use the search box to find a value, for example `Speed`. **Open interlock logic** goes to the interlock sheet of the unit, **Export CSV** saves the datasheet as a table, and **Ask about this datasheet** sends a question to the assistant."),
          FIG("p3_eq_ds", "Datasheet tab.",
              [(1, "**Open interlock logic**, **Export CSV** and **Ask about this datasheet**.", "^Open interlock logic$"),
               (2, "Key values shown as tiles at the top.", "^Cylinder Material$"),
               (3, "Search box for the 36 specifications.", "Search this datasheet"),
               (4, "Specification groups, each with a count.", "^Identification$")], maxh=130),
          H2("Interlock logic tab"),
          P("The tab shows the cause-and-effect sheet of the unit's interlock, with tabs for the **Function test** and the **Proof test history**. Chapter 16 explains the sheet."),
          H2("Lessons tab"),
          P("The Lessons tab lists the one point lessons that concern the equipment. Each card shows the lesson number, its discipline, its classification and the number of steps. **Open sheet** opens the lesson, and **Simulate** starts the matching exercise (Chapters 28 and 29)."),
          FIG("p3_eq_opl", "Lessons tab.", maxh=90),
          H2("Maintenance tab"),
          P("The Maintenance tab shows the maintenance dashboard for this one machine: work orders per month and by type, cost split, work by component, failure locations on the drawing and the reliability figures. It uses the same charts as the Maintenance page, limited to this set."),
          FIG("p3_eq_maint", "Maintenance tab.", maxh=120),
          H2("Related assets tab"),
          P("The last tab lists assets that are connected to this equipment, such as a cooler or a knock-out drum, with their tag, type and description."),
          FIG("p3_eq_rel", "Related assets tab.", maxh=60),
          ]
    # ------------------------------------------------------------------ 14 Drawings
    b += [H1(14, "Equipment drawings in 2D and 3D", ["Operator", "Engineer", "Reliability", "HSE", "Manager"], PART3,
             "Every machine has a general arrangement drawing and a 3D model built from the same list of parts. Selecting a part in either view shows its item number, material, drawing reference and simulated condition."),
          H2("The 2D drawing"),
          STEPS(["Open an equipment set and select the **Drawing and 3D** tab.",
                 "Make sure **2D drawing** is selected above the drawing.",
                 "Select a numbered balloon on the drawing, or a part name in the table below it. The part is highlighted.",
                 "Read the **Component details** panel. It shows the item number, part, material, quantity and drawing reference.",
                 "Tick **Live condition** to see a simulated reading for the part, such as bearing temperature or leak rate."]),
          FIG("p3_ga2d", "The 2D drawing with the mechanical seal selected.",
              [(1, "Switch between **2D drawing** and **3D model**.", "^2D drawing$"),
               (2, "Details of the selected part.", "^Component details$"),
               (3, "Simulated condition of the part. The signal is a demonstration, not a live reading.", "^Live condition$")], maxh=150),
          NOTE("note", "Amber boxes on the drawing mark nozzles and manways. A dashed outline means that a part is hidden or internal. The condition shading is green for normal, amber for alarm and red for trip."),
          H2("The 3D model"),
          STEPS(["Select **3D model** above the drawing.",
                 "Drag to rotate the machine and scroll to zoom.",
                 "Select a part on the model. The part is highlighted and an information card shows its item number, material, quantity and live condition.",
                 "Select another part. The card changes to that part.",
                 "Use the view buttons **Isometric**, **Front**, **Side** and **Top** to look from a fixed direction, **Auto-rotate** to turn the model, and **X-ray** to see through the casing.",
                 "Select **Moving parts** to animate shafts, impellers and fans. Select **Reset** to return to the first view."]),
          FIG("p3_ga3d", "The 3D model of the Feed/Charge Pump with a part selected.",
              [(1, "View buttons: Isometric, Front, Side, Top, Auto-rotate, X-ray, Moving parts and Reset.", "^Isometric$", -4, -14), ], maxh=150),
          P("The same approach works on every machine. The platform has separate models for the pump, the dryer, the reactor, the compressor, the heater, the separator, the cooling tower fan and the reflux drum."),
          FIG("p3_ga3d2", "The 3D model of the Polymer Fluid Bed Dryer with a part selected.", maxh=150),
          H2("Bill of material and work orders by component"),
          P("Under the drawing, the **Bill of material** lists the item number, part, material and quantity of every part. The **Nozzle and connection schedule** lists the nozzles with their size and remarks. The **Work orders by component** chart on the right counts the work orders raised for each part; select a bar to see them."),
          ]
    # ------------------------------------------------------------------ 15 P&ID
    b += [H1(15, "Live P&ID", ["Operator", "Engineer", "Reliability", "HSE", "Manager"], PART3,
             "The platform holds eight piping and instrumentation diagrams. Each is drawn in a consistent style, coloured by service, and connected to the interlock model, so that closing a valve or tripping an instrument shows what follows."),
          H2("Reading the diagram"),
          FIG("p3_pid", "The P&ID of the Recycle Gas Compressor.",
              [(1, "Title block with the drawing number and revision.", "^TJC-LLD-PID-4501", 0, -14),
               (2, "**Simulated live data** badge. The values are generated for demonstration.", "^SIMULATED LIVE DATA$"),
               (3, "Zoom controls: **−**, **Fit**, **+**. The **Values** button shows or hides the readings.", "^Fit$"),
               (4, "Status line: whether all items are healthy.", "^NORMAL$"),
               (5, "Help panel: select any item to open its datasheet context.", "^Select equipment$")], maxh=170),
          BUL(["Process lines are coloured by service: process liquid, nitrogen, steam, cooling water, lube oil and gas.",
               "Instrument bubbles show the tag and, when **Values** is on, the reading.",
               "Select a pump, vessel, valve or instrument to see its details and linked documents in the panel on the right.",
               "A red bubble means that the instrument has tripped. Red lines show the interlock effects."]),
          H2("Operating a valve"),
          STEPS(["Select a valve symbol on the diagram, for example `XV-4501`, the compressor suction valve.",
                 "Choose **Close** in the panel. The valve turns to closed.",
                 "Watch the flow. The lines downstream stop moving, and the permissives that depend on the valve change to failed.",
                 "Open the valve again to restore the flow."]),
          FIG("p3_pid_valve", "The suction valve XV-4501 closed. Flow downstream has stopped and the dependent permissive is shown as failed.", maxh=170),
          NOTE("caution", "The diagram is a simulation. Closing a valve here does not act on the plant."),
          H2("Simulating a trip"),
          P("The help panel states that **Simulate trip** on an initiating instrument makes the interlock effects follow: valves move, drives stop and flow halts. Use it to see which final elements an instrument acts on before you plan a function test."),
          ]
    # ------------------------------------------------------------------ 16 Interlock Library
    b += [H1(16, "Interlock Library", ALL, PART3,
             "The Interlock Library holds the cause-and-effect logic of every protective system. It shows which instruments initiate a trip, which final elements act and what must be true before the unit can start."),
          FIG("p3_il", "The Interlock Library.",
              [(1, "Summary tiles: safety instrumented functions, initiators, final elements and proof test records.", "^Safety instrumented functions$"),
               (2, "**Voting architecture**. Select a segment to filter the cards below.", "^Voting architecture$"),
               (3, "**Initiators and final elements** for each interlock. Select a row to open it.", "^Initiators and final elements by interlock$"),
               (4, "**Proof test records**. Select a column to see the history.", "^Proof test records$"),
               (5, "Search and filters by equipment and integrity level.", "Search interlock, tag or cause"),
               (6, "One card for each interlock with its SIL, counts and voting.", "^HEXANE FEED PUMP")], maxh=170),
          H2("Finding an interlock"),
          STEPS(["Use the search box to type a tag, a cause or an interlock name, for example `PSLL-1201`.",
                 "Filter by equipment or by integrity level (SIL 1, SIL 2 or non-SIS) if needed.",
                 "Select a card to open the interlock sheet."]),
          H2("The interlock sheet"),
          FIG("p3_il_open", "An interlock sheet.",
              [(1, "Tabs: **Interlock sheet**, **Function test** and **Proof test history**.", "^Interlock sheet$"),
               (2, "The cause-and-effect matrix. Each X shows a final element that acts on the trip.", "^2\\. CAUSE AND EFFECT MATRIX"),
               (3, "**Initiators**: each tag with its set point and voting.", "^Initiators$"),
               (4, "**Run function test** starts the simulated test.", "^Run function test$"),
               (5, "**Linked records**: the P&ID, drawing, datasheet, maintenance history and related lessons.", "^Linked records$")], maxh=170),
          P("The sheet has four sections: a description, the cause-and-effect matrix, the final elements with the initiators that act on each, and the start permissives. Select a row of the matrix to highlight its effects. A note such as `Completes P&ID data` means that the platform found the instrument in the interlock document but not on the P&ID, and has added it."),
          H2("Function test and proof test history"),
          FIG("p3_il_test", "The function test tab.", maxh=150),
          P("The **Function test** tab steps through the test of each initiator and shows the expected response of the final elements. The **Proof test history** tab lists the earlier proof tests with their dates and results, so that you can see when each function was last verified."),
          ]
    # ------------------------------------------------------------------ 17 Start-up readiness
    b += [H1(17, "Start-up readiness", ["Operator", "Engineer", "HSE", "Manager"], PART3,
             "Before a unit is started or restarted, the checks that normally sit in several places are evaluated on one page. The page ends with a single decision: GO, GO WITH CHECKS or NO-GO."),
          FLOW("f_ready", [[("pill", "Open the unit's Start-up readiness tab"), ("box", "Read the start permissives from the interlock logic"), ("box", "Compare with the P&ID and live conditions")],
                           [("box", "Check recent work orders and lessons"), ("dia", "Any blocker?", "Yes: NO-GO"), ("dia", "Any open check?", "Yes: GO WITH CHECKS"), ("pill", "GO: sign off")]],
               "How the readiness decision is reached."),
          FIG("p3_ready", "A unit with GO WITH CHECKS and several open checks.",
              [(1, "The decision for the unit: **GO**, **GO WITH CHECKS** or **NO-GO**.", "^GO WITH CHECKS$"),
               (2, "**Start permissives**, each with its signal and its current state.", "^Start permissives$"),
               (3, "**Trips and valves**: any latched trip or valve out of position.", "^Trips and valves$"),
               (4, "**Recent work** that could affect the start.", "^Recent work$"),
               (5, "**Decision** panel: open checks, **Sign off as Manager** and **Print handover note**.", "^Decision$")], maxh=170),
          H2("Reading the page"),
          BUL(["A green tick means that a permissive is satisfied. A grey circle means that the platform cannot confirm it from the data and that someone must check it in the field.",
               "A red cross means that the permissive is not satisfied. The page then shows **NO-GO**.",
               "The rule line at the bottom of the list states the logic, for example `ALL permissives TRUE (AND) => START ENABLED`."]),
          H2("Signing off"),
          STEPS(["Work through each open check. Close it, or accept it with a note.",
                 "Select **Sign off as** followed by your role. Only roles that may approve see the button.",
                 "Select **Print handover note** to produce a record of the checks for the next shift.",
                 "Select **Open the P&ID** to look at the diagram, or **Ask the assistant** to question the data."]),
          FIG("p3_ready_go", "A unit with no open checks.", maxh=130),
          ]
    # ------------------------------------------------------------------ 18 Documents
    b += [H1(18, "Documents", ALL, PART3,
             "The Documents page lists every controlled document in the knowledge base with its type, set, revision, approval status and effective date."),
          FIG("p3_docs", "The Documents page.",
              [(1, "**Documents by type**. Select a segment to filter the list.", "^Documents by type$"),
               (2, "**Approval status**: not stated, issued for construction or issued for operation.", "^Approval status$"),
               (3, "**Documents by equipment**. Select a bar to filter by set.", "^Documents by equipment$")], maxh=170),
          H2("Finding and opening a document"),
          STEPS(["Use the three filters to choose a document type, an equipment set and an approval status.",
                 "Read the table. The columns are the document identifier, the title, the type, the set, the revision, the approval status and the effective date.",
                 "Select a row to open the document. Its text is shown in sections, with the revision and status at the top."]),
          NOTE("caution", "Check the approval status before you rely on a document. A status of **Not stated** means that the source did not give one. The platform never treats such a document as approved."),
          H2("Document conflicts"),
          P("When two documents disagree, for example when a valve is labelled both trips OPEN and trips CLOSED, the platform records a conflict. The conflict count on the Dashboard links to the Data Quality page (Chapter 35). The AI Assistant also adds an **Open document conflict** note when its answer touches a document with a recorded conflict."),
          ]
    return b
